// corpus-v2 pair auction--rickyliu1117 (auctions, moderate)
// Auction.test.js: Auction > Auction End > Should not allow ending auction before end time
const { expect } = require("chai");
const { ethers } = require("hardhat");
let auction;
let owner;
let bidder1;
let bidder2;
let bidder3;
const BIDDING_TIME = 3600n;
// beforeEach of suite "Auction"
beforeEach(async function () {
        // Get signers (accounts)
        [owner, bidder1, bidder2, bidder3] = await ethers.getSigners();

        // Deploy the contract
        const Auction = await ethers.getContractFactory("Auction");
        auction = await Auction.deploy(BIDDING_TIME);
        await auction.waitForDeployment();
    })
it("Should not allow ending auction before end time", async function () {
            await expect(auction.endAuction())
                .to.be.revertedWithCustomError(auction, "AuctionNotEnded");
        })


